ij_java_method_parameters_right_paren_on_new_line = true
개인적으로는 A 스타일로 개발하다가 파라미터가 많아질수록 B 스타일 그리고 C 스타일로 변경하는 것 같고 D 스타일은 마음에 들지 않는데 자동으로 검출할 수가 없는 케이스라 PR 리뷰 단계에서 체크가 필요해보인다.

Invalid SockJS path ‘XXX’ required to have 3 path segments.

구글에 Invalid SockJS path 라는 키워드로 검색해보면 이와 같은 오류 로그에 대한 조치로 Stomp 클라이언트를 사용하라는 답변이나 스택 오버플로우에 질문하라는 답변을 찾아볼 수 있다. 아무튼 위 상황에 대한 원인은 명확히 알 수 없는 상황에서 아래와 같은 구조에서 해당 오류가 발생했다.

Nginx Websocket Proxy
Spring WebSocket with Stomp + SockJS
sockjs-client@1.6.1
@stomp/stompjs@7.0.0

이슈 파악
nginx.conf와 같이 엔진엑스에서 웹소켓 주소 패턴에 대해 백엔드 애플리케이션으로의 리버스 프록시 구성을 아래와 같이 해둔 상태였다. 그리고 Stomp 방식의 웹 소켓 연결을 수행하는 엔드포인트는 /ws/stomp 로 정의되어있었다. 본래 /ws 는 일반적인 웹 소켓 연결을 수행하고 /ws/stmop로 시작되는 것은 Stomp로 동작하는 것을 의도한 것이다.
nginx.confhttp &#123;
    upstream backend &#123;
        server app:8080;
        keepalive 128;
    &#125;

    server &#123;
        location &#x2F;ws&#x2F; &#123;
            proxy_pass http:&#x2F;&#x2F;backend;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            # hop-by-hop
            proxy_http_version 1.1;
            proxy_set_header Connection &quot;upgrade&quot;;
            proxy_set_header Upgrade $http_upgrade;
            proxy_read_timeout 65s;
        &#125;
    &#125;
&#125;

Vite 개발 서버에서의 Proxy 구성의 경우 올바르게 Stomp 방식의 웹소켓 연결을 수행된다.

하지만, 엔진엑스와 함께 동작중인 배포 환경에서는 Stomp 클라이언트가 SockJS를 사용하여 연결을 수행하려고 할때 /ws/stomp/info?t=0 엔드포인트에 대해 404 응답을 받게되고 애플리케이션 로그에는 Invalid SockJS path ...가 출력되는 것을 확인했다.
솔루션
이리저리 시도해본 결과 해결책은 일반적인 웹 소켓 연결과 Stomp 방식의 연결을 아예 분리하는 것이다. /ws/ 이외에 /ws-stomp/로 Stomp 방식의 웹 소켓 연결을 위한 별도의 엔드포인트 패턴을 사용하고 리버스 프록시 구성을 하고나니 해당 증상은 발생하지 않았다.
nginx.confhttp &#123;
    upstream backend &#123;
        server app:8080;
        keepalive 128;
    &#125;

    server &#123;
        location ~ ^&#x2F;(ws|ws-stomp)&#x2F; &#123;
            proxy_pass http:&#x2F;&#x2F;backend;
            proxy_set_header Host $host;
            proxy_set_header X-Real-IP $remote_addr;
            proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
            # hop-by-hop
            proxy_http_version 1.1;
            proxy_set_header Connection &quot;upgrade&quot;;
            proxy_set_header Upgrade $http_upgrade;
            proxy_read_timeout 65s;
        &#125;
    &#125;
&#125;
아무튼 정확한 원인에 대해서는 별도로 찾아보아야겠지만 기록으로 남기고자 한다.

■ 개인정보의 기술적관리적 보호조치 기준 제10조
정보통신서비스 제공자등은 개인정보 업무처리를 목적으로 개인정보의 조회, 출력 등의 업무를 수행하는 과정에서 개인정보보호를 위하여 개인정보를 마스킹하여 표시제한 조치를 취할 수 있다.

위와 같이 개인정보 또는 보안 이슈로 인하여 일부 민감한 데이터 항목을 전체가 아닌 일부만을 표시해야할 요구사항이 있을 수 있다. Jackson AnnotationIntrospector 이슈를 경험한 김에 AnnotationIntrospector를 사용하여 REST API에서 응답되는 일부 필드를 마스킹하는 방법을 이해해보도록 하자.
Annotation 기반 마스킹 처리
기본적으로 별도의 Getter 함수로 만들어서 마스킹한 결과를 반환하는 필드를 만들어내도 된다. 그러나, 마스킹을 위한 어노테이션을 만들고 AnnotationIntrospector를 확장해서 어노테이션이 선언된 필드에 대해서 마스킹된 결과로 직렬화(Serialize)를 수행하도록 작성하면 마스킹 되어야하는 항목에 따라서 다양한 마스킹 패턴을 전략적으로 적용할 수 있다.
MaskedField@Target(&#123;ElementType.ANNOTATION_TYPE, ElementType.FIELD&#125;)
@Retention(RetentionPolicy.RUNTIME)
@JacksonAnnotation
public @interface MaskedField &#123;
    String expression() default "****";
    MaskedType type() default MaskedType.COMMON;
    String[] fields() default &#123;&#125;; // NOTE: If metadata
&#125;
MaskedFieldAnnotationIntrospectorpublic class MaskedFieldAnnotationIntrospector extends NopAnnotationIntrospector &#123;

    @Override
    public Object findSerializer(Annotated annotated) &#123;
        MaskedField annotation = annotated.getAnnotation(MaskedField.class);
        if (annotation != null) &#123;
            return MaskedFieldSerializer.class;
        &#125;
        return null;
    &#125;

    public static class MaskedFieldSerializer extends StdSerializer&lt;Object> implements ContextualSerializer &#123;
        private final boolean isMask;
        private final MaskedField annotation;

        public MaskedFieldSerializer(MaskedField annotation, boolean isMask) &#123;
            super(Object.class);
            this.isMask = isMask;
            this.annotation = annotation;
        &#125;

        @Override
        public void serialize(Object value, JsonGenerator gen, SerializerProvider provider) throws IOException &#123;
            // NOTE: MaskedType 에 따른 마스킹 패턴 구현은 생략
            ObjectMapper mapper = (ObjectMapper) gen.getCodec();
            String s = mapper.writeValueAsString(value);
            if (isMask) &#123;
                JSONParser parser = new JSONParser(DEFAULT_PERMISSIVE_MODE);
                try &#123;
                    Object o = parser.parse(s);
                    if (o instanceof JSONAwareEx ex) &#123;
                        DocumentContext doc = JsonPath.parse(ex.toJSONString());
                        Map json = doc.json();
                        for (String field : annotation.fields()) &#123;
                            if (json.containsKey(field)) &#123;
                                doc.set(field, annotation.expression());
                            &#125;
                        &#125;
                        gen.writeRawValue(doc.jsonString());
                    &#125; else &#123;
                        gen.writeString(annotation.expression());
                    &#125;
                &#125; catch (ParseException e) &#123;
                    e.printStackTrace();
                &#125;
            &#125; else &#123;
                gen.writeRawValue(s);
            &#125;
        &#125;

        @Override
        public JsonSerializer&lt;?> createContextual(SerializerProvider serializerProvider, BeanProperty beanProperty) throws JsonMappingException &#123;
            MaskedField maskedField = null;
            if (beanProperty != null) &#123;
                maskedField = beanProperty.getAnnotation(MaskedField.class);
            &#125;
            return new MaskedFieldSerializer(maskedField, true);
        &#125;
    &#125;
&#125;
AnnotationIntrospector.pair@Bean
