    &#125;
&#125;);

thread.setName("Mail-Thread");
thread.setDaemon(true);
thread.start();
Spring Retry를 통한 메일 발송 실패 시 재시도 전략 - Guide to Spring Retry
이메일 발송 실패 건에 대해서 Spring Retry를 통해 재시도 로직을 쉽게 구현할 수 있다. 메일 발송을 위한 RetryTemplate 구성 시 재시도 전략을 구성하고 메일을 발송하는 함수를 RetryTemplate로 감싸면 된다. context.getRetryCount() 함수를 통해 재시도 횟수를 가져올 수 있다.
RetryTemplate retryTemplate = new RetryTemplateBuilder()
        .maxAttempts(3)
        .exponentialBackoff(Duration.ofSeconds(10L), 2, Duration.ofMinutes(1L))
        .retryOn(List.of(MessagingException.class, MailException.class))
        .build();

BlockingQueue&lt;MimeMessage> waitingQueue = new LinkedBlockingQueue&lt;>(50000);

Thread thread = new Thread(() -> &#123;
    while (true) &#123;
        if (waitingQueue.isEmpty()) &#123;
            continue;
        &#125;

        retryTemplate.execute(context -> &#123;
            try &#123;
                MimeMessage message = waitingQueue.take();
                javaMailSender.send(message);
            &#125; catch (Throwable e) &#123;
                log.error(e.getMessage(), e);
            &#125;
        &#125;);
    &#125;
&#125;);

thread.setName("Mail-Thread");
thread.setDaemon(true);
thread.start();
Guava RateLimiter를 통한 초당 이메일 발송 시도 제한 - Quick Guide to the Guava RateLimiter
AWS SES의 발신 한도 중에는 초당 보낼 수 있는 이메일 수에 대한 제한량이 있으므로 Guava RateLimiter를 통해 초당 이메일 발송 수를 넘어서지 않도록 방어하는 코드를 작성할 수 있다. 물론, SMTP 서버를 다수의 애플리케이션 서버에서도 연결할 가능성이 있으므로 발신 할당량에 대한 모니터링 및 발신 한도를 별도로 관리할 필요는 있다.
RateLimiter rateLimiter = RateLimiter.create(14);

Thread thread = new Thread(() -> &#123;
    while (true) &#123;
        if (waitingQueue.isEmpty()) &#123;
            continue;
        &#125;

        boolean acquire = rateLimiter.tryAcquire(1);
        if (acquire) &#123;
            executor.execute(() -> &#123;
                try &#123;
                    MimeMessage message = waitingQueue.take();
                    javaMailSender.send(message);
                &#125; catch (Throwable e) &#123;
                    log.error(e.getMessage(), e);
                &#125;
            &#125;);
        &#125;
    &#125;
&#125;);
thread.setName("Mail-Thread");
thread.setDaemon(true);
thread.start();

Guava RateLimiter는 초당 호출에 대한 제한만 가능하므로 분당 이메일 발송을 제한하고 싶다면 Resilience4j의 RateLimiter를 도입해야합니다.

Resilience4j CircuitBreaker를 통한 메일 발송 중단 - Guide to Resilience4j
SMTP 서버의 발신 한도 제한을 넘어서는 경우에 대한 장애 처리를 위해 Resilience4j를 도입할 수 있다. 하루동안 메일을 보낼 수 있는 할당량을 초과하거나 초당 보낼 수 있는 이메일 수에 제한이 되었다면 일정 시간동안 이메일 발송을 시도하지 않도록 CircuitBreaker를 사용하여 장애 전파 방지를 구현할 수 있다. AWS SES의 발신 한도인 아래의 두개 항목에 대해서 처리를 고려하도록 하자.

454 Throttling failure: Maximum sending rate exceeded (1초당 이메일 발송 수 제한량)
454 Throttling failure: Daily message quota exceeded (24시간 당 이메일 발송 할당량)

CircuitBreaker circuitBreaker = CircuitBreaker.ofDefaults("MailSendingLimitExceeded");
RateLimiter rateLimiter = RateLimiter.create(14);

Thread thread = new Thread(() -> &#123;
    while (true) &#123;
        if (waitingQueue.isEmpty()) &#123;
            continue;
        &#125;

        boolean permission = circuitBreaker.tryAcquirePermission();
        permission &amp;= rateLimiter.tryAcquire(1);
        if (permission) &#123;
            executor.execute(() -> &#123;
                try &#123;
                    MimeMessage message = waitingQueue.take();
                    javaMailSender.send(message);
                &#125; catch (Throwable e) &#123;
                    String failReason = e.getMessage();
                    if (failReason != null
                            &amp;&amp; failReason.contains("454 Throttling failure")) &#123;
                        circuitBreaker.transitionToClosedState();
                    &#125;
                    log.error(failReason, e);
                &#125;
            &#125;);
        &#125;
    &#125;
&#125;);
thread.setName("Mail-Thread");
thread.setDaemon(true);
thread.start();
JavaMailSenderImpl은 매번 연결한다?!
일부 시스템 환경에서 AWS SES의 SMTP 서버를 동일한 리전이 아닌 상당히 멀리 떨어져있는 리전에 구성된 SMTP를 통해 메일 발송을 시도하는 경우 커넥션에 대한 소요 시간이 크다는 것을 알 수 있었다. 예를 들어, US East (Ohio) 리전의 SMTP 엔드포인트를 Asia Pacific (Seoul) 리전에서 연결하는 경우 약 2초 정도의 시간이 소요되는데 동일한 리전에서 연결하면 약 100ms 가 걸린다.
JavaMailSenderImpl의 connectTransport 함수를 사용하여 testConnection 또는 doSend 함수에서 연결을 수행하는 것을 확인할 수 있는데 MimeMessage 목록을 send 함수 파라미터로 전달할 때 연결을 수행하고 해제하므로 이메일을 하나씩 보내도록 구현했다면 이메일을 보낼때마다 연결을 수행하는 것이다.
JavaMailSenderImplprotected Transport connectTransport() throws MessagingException &#123;
    String username = this.getUsername();
    String password = this.getPassword();
    if ("".equals(username)) &#123;
        username = null;
        if ("".equals(password)) &#123;
            password = null;
        &#125;
    &#125;

    Transport transport = this.getTransport(this.getSession());
    transport.connect(this.getHost(), this.getPort(), username, password);
    return transport;
&#125;
SimpleJavaMail의 Batch Module은 Transport 연결에 대한 커넥션 풀을 사용한다고 되어있으므로 SMTP 서버로의 연결 수행시간이 오래걸린다면 Transport 에 대한 커넥션 풀을 이용해보는 것도 좋은 방법으로 생각된다.

자바 신입 개발자 면접 질문 중에 멀티스레드와 동시성 문제는 대부분의 회사에서 단골 질문에 해당한다. 조직의 주니어 개발자가 멀티스레드를 고려하지 않고 비즈니스 요구사항을 처리하기 위해 코드를 수정한 결과로 인해 시스템에서 주요 기능 중 하나인 이벤트 모니터링 화면에서 데이터가 간헐적으로 올바르지 않은 문제가 발생함이 리포트 되었다.
동시성 문제가 발생하는 코드
멀티스레드에 의한 병렬 처리 시 동시성 문제가 발생했던 비즈니스 로직 코드는 대충 아래와 같다고 볼 수 있다.
List&lt;Customer> customers = IntStream.rangeClosed(1, 100)
                .mapToObj(i -> new Customer().setId(String.valueOf(i)))
                .toList();

List&lt;String> optIds = new ArrayList&lt;>();
customers.parallelStream().forEach(customer -> &#123;
    optIds.add(customer.getId());

    // customer 에 대한 데이터 조회 로직
&#125;);
System.out.println("expected: 100, size: " + optIds.size());
위 코드에서 ArrayList 에 저장되는 목록의 결과가 매번 동일함이 보장이 되는가? 가 중요한 부분인데 실제로 테스트 코드를 돌려보면 간헐적으로 100개가 아닌 97개가 목록에 포함되는 경우를 확인할 수 있을 것이다. 멀티스레드에 의해서 add 함수가 동시에 호출되는 경우에는 ConcurrentModificationException와 같은 예외가 발생하지 않는게 중요한 부분이다.
ArrayList 와 HashSet에 대한 동기화 컬렉션
일반적으로 많이 사용되는 ArrayList 과 HashSet 에 데이터를 추가할 때 ParallelStream 을 사용하는 경우 위와 같이 동시성 문제로 인해 제대로 추가되지 않는 항목이 존재할 수 있다. 이로 인한 동시성 문제를 해결하기 위해서는 아래와 같이 Synchronized 키워드를 사용하거나 동기화 문제를 고려한 컬렉션 클래스들이 존재한다.

ConcurrentSkipListSet
CopyOnWriteArrayList
Collections.synchronizedList();
CopyOnWriteArraySet
Collections.synchronizedSet();
ConcurrentHashMap.newKeySet();

동시성 문제가 발생했던 비즈니스 로직에서 CopyOnWriteArrayList 와 CopyOnWriteArraySet은 쓰기 작업에 대한 오버헤드가 있다는 점을 고려하여 Collections.synchronizedList 를 사용하는 것으로 결정하여 수정하였다.

자바에서 병렬처리 시 동시성을 고려해야하는 것은 기초적인 부분에 해당되어 주니어 개발자에게 아쉬운 부분이긴 하나 이러한 문제를 내재하게 된 가장 큰 원인은 요구사항을 처리한 당시에 개발 리드로써 코드 리뷰를 상세하게 해주지 않았던 것이므로 스스로 반성해야할 부분이라 생각됩니다.

자바에서 날짜 및 시간을 다루는 경우 Instant, OffsetDateTime 또는 ZonedDateTime과 같이 타임존 오프셋이 포함되는 것을 활용하는 것이 좋습니다. 그런데, 가끔은  연,월,일 통계와 같은 요구사항으로 인해 YearMonth 또는 LocalDate를 사용해야하는 경우가 있습니다. 예를 들어, 2025년 2월에 대한 통계를 위해서 2025년 2월의  첫번째 날짜와 마지막 날짜의 범위를 알아야 합니다. 첫번째 날짜는 명확하므로 간단하지만 마지막 날짜는 월마다 다른데 특히나, 2월의 마지막 날짜는 28일이기도 합니다.
자바에서 연 또는 월에 대한 마지막 날짜를 가져오는 방법을 여러가지가 있습니다. Year 또는 YearMonth의 lengthXXX 함수를 통해 마지막 날짜를 가져와서 지정할 수 있으며 YearMonth 에는 더 직관적인 atEndOfMonth 함수를 포함하고 있습니다. 또한,  TemporalAdjusters를 통해 날짜를 변환하는 것도 가능하죠.
월 누적을 위한 첫번째 날짜와 마지막 날짜 가져오기
YearMonth yearMonth = YearMonth.of(2025, 2);
LocalDate startDate = yearMonth.atDay(1);
LocalDate endDate = yearMonth.atEndOfMonth();

마지막 날짜를 구하기 위해서 YearMonth.lengthOfMonth 또는 TemporalAdjusters.lastDayOfMonth 함수를 이용할 수도 있습니다.

연 누적을 위한 첫번째 날짜와 마지막 날짜 가져오기
Year year = Year.of(2025);
LocalDate firstDate = year.atDay(1);
LocalDate lastDate = year.atDay(year.length());

마지막 날짜를 구하기 위해서 TemporalAdjusters.lastDayOfYear 함수를 이용할 수도 있습니다.

스프링 컨트롤러 핸들러 함수 파라미터
@RestController
@RequestMapping("/api")
public class SampleApi &#123;
    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy.MM.dd");

    @InitBinder
    public void initBinder(WebDataBinder binder) &#123;
        binder.registerCustomEditor(Month.class, new MonthPropertyEditor());
    &#125;

    @GetMapping("/stat/&#123;year:[0-9]&#123;4&#125;&#125;")
    public ResponseEntity&lt;?> getStatOfYear(@PathVariable("year") Year year) &#123;
        LocalDate fromDate = year.atDay(1);
        LocalDate toDate = year.atDay(year.length());
        return ResponseEntity.ok(Map.of(
                "from", fromDate.format(DATE_FORMAT),
                "to", toDate.format(DATE_FORMAT)));
    &#125;

    @GetMapping("/stat/&#123;yearMonth:[0-9]&#123;4&#125;\\-[0-9]&#123;2&#125;&#125;")
    public ResponseEntity&lt;?> getStatOfYearMonth(
            @DateTimeFormat(pattern = "yyyy-MM")
            @PathVariable("yearMonth") YearMonth yearMonth) &#123;
        LocalDate fromDate = yearMonth.atDay(1);
        LocalDate toDate = yearMonth.atEndOfMonth();
        return ResponseEntity.ok(Map.of(
                "from", fromDate.format(DATE_FORMAT),
                "to", toDate.format(DATE_FORMAT)));
    &#125;

    @GetMapping("/stat/&#123;year&#125;/&#123;month&#125;")
    public ResponseEntity&lt;?> getStatOfYearMonth(@PathVariable("year") Year year,
                                                @PathVariable("month") Month month) &#123;
        return getStatOfYearMonth(YearMonth.of(year.getValue(), month));
    &#125;

    private static class MonthPropertyEditor extends PropertyEditorSupport &#123;
        @Override
        public void setAsText(String text) throws IllegalArgumentException &#123;
            if (text.matches("\\d+")) &#123;
                setValue(Month.of(Integer.parseInt(text)));
                return;
            &#125;
            setValue(Month.valueOf(text.toUpperCase()));
        &#125;
    &#125;
&#125;
스프링 컨트롤러의 핸들러 함수를 작성할 때 연도와 월에 대한 파라미터를 int 가 아닌  Year와 YearMonth를 그대로 활용할 수 있도록 바인딩이 가능합니다. 단,  Month의 경우 클래스가 아닌 Enum 이기 때문에 별도의  PropertyEditor를 작성하여  WebDataBinder에 등록해야합니다. 파라미터 바인딩으로 변환하는 과정을 공통적으로 적용하므로 더 효율적이고 직관적인 코드를 작성할 수 있음을 알았습니다.

